insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('9f3a4fa6-f3f0-490c-9355-ca0523f86aca', 'BIO FÀCIL GRAS S.A.S', generar_slug_unico('BIO FÀCIL GRAS S.A.S', '9f3a4fa6-f3f0-490c-9355-ca0523f86aca'), (select id from categorias_oficiales where slug = 'ecoproductos-industriales'), 'Rionegro', (select id from veredas where municipio = 'Rionegro' and slug = 'la-ceiba'), 'VEREDA LA CEIBA PARCELA VILLA GRACIA', 7.441166666666667, -73.19572333333333, 'Una vez se recepcióna el sebo en la planta de producción pasa al área de molido se dispone el material al alimentador del molino, este va transportado por…', 'Una vez se recepcióna el sebo en la planta de producción pasa al área de molido se dispone el material al alimentador del molino, este va transportado por el sifin del molino, el cual pasa por una transformación de prensado y cortado por una cuchilla, el cual sale expulsado por la bocilla de molino y cae directamente a una paila la cual tiene una capacidad de 400 kg de grasa molida. Esta carga require de una cocción de 120 minutos a 170 grados la cual se realiza por combustion directa, posteriormente la materia prima sufre un proceso de transformación físico químico (solido a liquido) en esta parte de proceso   se observa una viscosidad amarillenta; pasamos a la parte final de proceso cual consta de 60 minutos donde se llega a su transformación final de aspecto transparente y las partículas que no se descompusieron en su totalidad se denominan proteína carne una particularidad es que flotan ; terminada esta etapa del proceso se abre la llave de paso de vaciado por la cual el aceite sale expulsado con su proteína  y es atrapado por un colador industrial ; este material es evacuado por baches  de expulsion de aceite depositados en un recipiente metálico, para su enfriamiento  es llevado al área de empace el cual se realiza en cónstales  de polipropileno los caules tienen una capacidad de 40 kilos.', 'RECOLECCION Y TRATAMIENTO FISICO DE ACEITES DE COCINA DE UN SOLO USO', '3227891306', null, 'biofacilgras@gmail.com', 'YOANA ALCIRA GIL QUINTERO', '901322670-5', 'Jurídica', null, '80 meses', 'Camara de comercio', 'DIANA NAVARRO', 'ACTIVO', 'Dinamizadoras', null, 2022, '464.7', 'ACTUALIZO', 'Se realizo visita y se actualizo ficha de verificacion', null, 'SI', 'NO', null, 'NO', null, 'NO', 'NO', 'SI', null, 'Jurídica', null, null, null, null, null, null, null, null, null, 'NO', 'MIXTO', 'NO', 'NO', 'Se requiere para el fortalecimiento de la marca', 'Cursos con FUNDESAN', 'N.A', 'NO', 'Certificado de SEYCA para la licencia ambiental sobre el CEBO', 'En proceso, contamos con pagina web.', null, 'Procesos limpios. -Disposición final de nuestros residuos. -Recuperadores de material biológico (expendios de carne), cuya recolección se hace En canastillas plásticas y su trasporte vehículo Tipo furgón. -Contamos con el GSA (sistema de gestión ambiental). -Combustión con cascarilla de palma. -Frecuencia de recolección diaria lo cual evita los olores contaminan el medio ambiente, minimiza el lixiviado. -Botellas de amor. -Dia sin bolsa.', 'Talento humano Idóneo. -Articulación institucional. -Mejoras de las unidades productivas locativas “Fritaderos”. -Mejora continua de los procesos” entrega de molinos, -Canecas, bolsas plásticas, guantes. -Capacitación Continua. -Facilidades de pago. -Sentido de partencia en la actividad Económica. -Interacción permanente con los clientes. -Programa emprendedor. -Mejoramiento en la calidad de vida (educativo)', 'Pagos contra entrega. -Aprobación oportuna de avances solicitados -Adelantos a cero intereses. -No castiga el precio por avance económico. -Facilidades de pago en maquinaria. -Cumplimiento en la frecuencia de recolección. -Actualización de precios de acuerdo al comportamiento Del mercado. -Sensibilización acerca de la economía circular', 'Falta de acompañamiento institucional. -Temor a las autoridades ambientales. -No hay revelo generacional. -Normatividad muy técnica y poco especifica. -Monopolio del mercado. -Competencia desleal por parte de la informalidad', 'N.A', 'Retardo en algunas transacciones por conectiva.', false, false, true, false, false);
