cia de trazas de contaminantes, asegurando la pureza y seguridad del alimento desde la materia prima hasta el producto final.
insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('d8baef9f-996a-4572-96f0-f7349480d88f', 'ELIZA COSTURA CREATIVA', generar_slug_unico('ELIZA COSTURA CREATIVA', 'd8baef9f-996a-4572-96f0-f7349480d88f'), (select id from categorias_oficiales where slug = 'ecoproductos-industriales'), 'Girón', (select id from veredas where municipio = 'Girón' and slug = 'acapulco'), 'MANZANA 9 LOTE 6A VEREDA ACAPULCO GIRÓN', 73.13573500000001, -7.008906666666666, 'Eliza costura creativa es un emprendimiento dedicado a la confección y comercialización de productos textiles sostenibles. su actividad principal se centra…', 'Eliza costura creativa es un emprendimiento dedicado a la confección y comercialización de productos textiles sostenibles. su actividad principal se centra en la producción de bolsas ecológicas y organizadores a partir de materiales que promueven la reducción de residuos y el uso de fibras naturales.', 'BOLSAS ECOLÓGICAS CON TELAS NATURALES Y RETAL DE TAPICERÍA', '3195363244', null, 'elizacosturacreativa@gmail.com', 'ELIZABETH PARRA DELGADO', '635184489', 'Natural', null, '6 MESES', 'Rut', 'CRISTAL VILLAREAL', 'ACTIVO', 'Intermedio', null, 2025, '1023,8 msnm', 'ACTUALIZO', 'Se actualizo ficha de verificación y plan de mejora', null, 'NO', 'ACUEDUCTO VEREDAL', null, null, null, 'NO', 'NO', 'NO', 'SI', 'Natural', null, null, null, null, null, null, null, null, null, 'NO', 'B2C', null, null, 'ESTANDARIZACIÓN, LA GESTIÓN DOCUMENTAL, COMPLEMENTADO CON LA IMPLEMENTACIÓN DE HERRAMIENTAS DE INGENIERÍA DE PROCESOS COMO EL FLUJO DE PROCESOS, FICHA TÉCNICA DEL PRODUCTO, COSTEO INTEGRAL Y TRAZABILIDAD. EL EMPRENDIMIENTO DEBE ESTABLECER INSTRUMENTOS FORMALES DE GESTIÓN AMBIENTAL, COMO LA MATRIZ DE IDENTIFICACIÓN DE IMPACTOS AMBIENTALES, EL PLAN DE GESTIÓN INTEGRAL DE RESIDUOS SÓLIDOS (PGIRS) Y MEDICIÓN DE RIESGOS.', 'FORMALIZACIÓN Y LA GESTIÓN SISTÉMICA DEL TRIPLE IMPACTO, SIENDO INDISPENSABLE LA CAPACITACIÓN EN CONTABILIDAD Y FINANZAS BÁSICAS, GESTIÓN AMBIENTAL REGULATORIA, SISTEMAS DE SOSTENIBILIDAD, PLANEACIÓN ESTRATÉGICA Y MÉTRICAS DE SOSTENIBILIDAD', 'NO REQUIERE', null, 'NO', 'REDUCCIÓN DE RESIDUOS TEXTILES: AL DAR UNA SEGUNDA VIDA AL RETAL DE TAPICERÍA', 'PARTICIPACIÓN EN FERIA DE REGIONAL DE NEGOCIOS VERDE 2024 Y 2025', 'EL NEGOCIO TIENE UNA BASE SÓLIDA DE ECONOMÍA CIRCULAR, DEMOSTRADA POR LA APLICACIÓN DE ESTRATEGIAS DE ECODISEÑO EN CIERTAS ETAPAS, EL USO DE MATERIALES RECICLADOS/RECUPERADOS', 'SU MODELO DE NEGOCIO PROMUEVE UN CAMBIO EN LA MENTALIDAD DEL CONSUMIDOR. ANIMAN A LAS PERSONAS A ELEGIR PRODUCTOS CON UNA HISTORIA, QUE APOYAN A UN EMPRENDEDOR LOCAL Y QUE TIENEN UN IMPACTO POSITIVO EN EL MEDIO AMBIENTE.', 'LA VIABILIDAD ECONÓMICA ES SÓLIDA EN SU FASE INICIAL', 'AUSENCIA DE GESTIÓN Y CONTROL FORMAL, YA QUE NO CUENTA CON INSTRUMENTOS COMO LA MATRIZ DE IDENTIFICACIÓN DE IMPACTOS (MIVIAN) NI EL PLAN DE GESTIÓN INTEGRAL DE RESIDUOS SÓLIDOS (PGIRS), LO CUAL IMPIDE LA MEDICIÓN RIGUROSA DE SU DESEMPEÑO Y EL CONTROL DE RIESGOS.', 'FALTA DE FORMALIZACIÓN EN SU COMPROMISO SOCIAL EXTERNO, PUES NO DESARROLLA MECANISMOS SISTEMÁTICOS DE COMUNICACIÓN Y RESPUESTA CON SUS COMPRADORES', 'FALTA DE ESTANDARIZACIÓN Y PLANEACIÓN ESTRATÉGICA, YA QUE NO TIENE DEFINIDO EL FLUJO DE PROCESOS CON TIEMPOS ESTÁNDAR NI CUENTA CON FICHA TÉCNICA FORMAL PARA SUS PRODUCTOS, AFECTANDO LA TRAZABILIDAD Y EL CÁLCULO EXACTO DE LA MANO DE OBRA.', true, false, false, false, false);
